namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public int RecipeCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple, classic pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.", "Serve immediately with extra cheese and pepper."],
            AverageRating = 4.8, RatingCount = 31
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
            Steps = ["Marinate chicken in yogurt and spices for at least 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger until soft.", "Add spices and tomato puree; simmer 15 minutes.", "Stir in cream and add chicken pieces.", "Simmer 10 minutes and serve with rice or naan."],
            AverageRating = 4.7, RatingCount = 19
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Description = "A tangy, sweet stir-fried noodle dish loaded with vegetables.",
            Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Sugar"],
            Steps = ["Soak rice noodles in warm water for 20 minutes; drain.", "Press and cube tofu; fry until golden.", "Make sauce: mix tamarind paste, fish sauce, sugar, and lime juice.", "Stir-fry vegetables until crisp-tender.", "Add noodles and sauce; toss to coat.", "Top with peanuts, bean sprouts, and lime wedges."],
            AverageRating = 4.3, RatingCount = 15
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
            Steps = ["Brown ground beef with diced onion.", "Add taco seasoning and water; simmer until thickened.", "Warm taco shells in the oven.", "Fill shells with beef mixture.", "Top with shredded lettuce, diced tomato, cheese, and sour cream."],
            AverageRating = 4.1, RatingCount = 27
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cake with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F (220°C). Butter and flour ramekins.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla; fold into chocolate mixture.", "Stir in flour until just combined.", "Pour into ramekins and bake 12-14 minutes.", "Invert onto plates and serve immediately."],
            AverageRating = 4.9, RatingCount = 42
        },
        new()
        {
            Id = 7, Title = "Greek Salad", Category = "Salads",
            Description = "A refreshing Mediterranean salad with feta and olives.",
            Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Red wine vinegar", "Oregano"],
            Steps = ["Chop cucumber, tomatoes, and red onion into chunks.", "Combine vegetables in a large bowl.", "Add olives and crumbled feta.", "Drizzle with olive oil and red wine vinegar.", "Season with oregano, salt, and pepper; toss gently."],
            AverageRating = 4.2, RatingCount = 18
        },
        new()
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh, creamy avocado dip with lime and cilantro.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps = ["Halve and pit avocados; scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, jalapeño, tomato, and cilantro.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
            AverageRating = 4.6, RatingCount = 33
        },
        new()
        {
            Id = 9, Title = "Miso Soup", Category = "Asian",
            Description = "A light, savory Japanese soup with tofu and seaweed.",
            Ingredients = ["Dashi stock", "Miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
            Steps = ["Bring dashi stock to a simmer.", "Add cubed tofu and rehydrated wakame.", "Remove from heat; dissolve miso paste into the broth.", "Ladle into bowls and garnish with sliced green onions."],
            AverageRating = 4.4, RatingCount = 12
        },
        new()
        {
            Id = 10, Title = "Palak Paneer", Category = "Indian",
            Description = "Creamy spinach curry with cubes of paneer cheese.",
            Ingredients = ["Spinach", "Paneer", "Onion", "Garlic", "Ginger", "Green chili", "Cream", "Cumin", "Garam masala"],
            Steps = ["Blanch spinach and blend into a smooth puree.", "Fry paneer cubes until golden; set aside.", "Sauté onion, garlic, ginger, and green chili.", "Add spices, then stir in spinach puree.", "Simmer 10 minutes; add cream and paneer.", "Serve hot with naan or rice."],
            AverageRating = 4.5, RatingCount = 16
        }
    ];

    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Italian", Description = "Pasta, pizza, and Mediterranean classics", Icon = "🍝", RecipeCount = 2 },
        new() { Name = "Indian", Description = "Rich curries and aromatic spice blends", Icon = "🍛", RecipeCount = 2 },
        new() { Name = "Asian", Description = "Stir-fries, noodles, and umami flavors", Icon = "🥢", RecipeCount = 2 },
        new() { Name = "Mexican", Description = "Bold flavors with fresh salsas and spices", Icon = "🌮", RecipeCount = 2 },
        new() { Name = "Desserts", Description = "Sweet treats and indulgent bakes", Icon = "🍰", RecipeCount = 1 },
        new() { Name = "Salads", Description = "Fresh, healthy, and colorful bowls", Icon = "🥗", RecipeCount = 1 }
    ];

    // Thread-safe rating storage: recipeId -> list of ratings
    private readonly Dictionary<int, List<int>> _ratings = [];
    private readonly Lock _ratingsLock = new();

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public (double Average, int Count) SubmitRating(int recipeId, int stars)
    {
        stars = Math.Clamp(stars, 1, 5);
        lock (_ratingsLock)
        {
            if (!_ratings.ContainsKey(recipeId))
                _ratings[recipeId] = [];

            _ratings[recipeId].Add(stars);

            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                var allRatings = _ratings[recipeId];
                recipe.AverageRating = Math.Round(allRatings.Average(), 1);
                recipe.RatingCount += 1;
            }

            return (recipe?.AverageRating ?? 0, recipe?.RatingCount ?? 0);
        }
    }

    public void AddRecipe(string title, string ingredients, string steps)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = title,
            Category = "Community",
            Description = $"A community-submitted recipe for {title}.",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });

        // Update or add Community category
        var community = _categories.FirstOrDefault(c => c.Name == "Community");
        if (community is null)
        {
            _categories.Add(new RecipeCategory
            {
                Name = "Community",
                Description = "Recipes shared by our community members",
                Icon = "👨‍🍳",
                RecipeCount = 1
            });
        }
        else
        {
            community.RecipeCount++;
        }
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => _hoveredStar = star"
                  @onmouseout="() => _hoveredStar = 0"
                  role="button"
                  aria-label="Rate @star stars">
                ★
            </span>
        }
    </div>
    <span class="rating-info">@AverageRating.ToString("0.0") avg · @RatingCount ratings</span>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selectedStar = stars;
        var (avg, count) = RecipeService.SubmitRating(RecipeId, stars);
        AverageRating = avg;
        RatingCount = count;
        _submitted = true;
    }
}

