+            <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
+                  @onclick="() => Rate(star)"
+                  @onmouseover="() => _hoveredStar = star"
+                  @onmouseout="() => _hoveredStar = 0"
+                  role="button"
+                  aria-label="Rate @star stars">
+                ★
+            </span>
+        }
+    </div>
+    <span class="rating-info">@AverageRating.ToString("0.0") avg · @RatingCount ratings</span>
+    @if (_submitted)
+    {
+        <span class="rating-thanks">Thanks for rating!</span>
+    }
+</div>
+
+@code {
+    [Parameter] public int RecipeId { get; set; }
+    [Parameter] public double AverageRating { get; set; }
+    [Parameter] public int RatingCount { get; set; }
+
+    private int _hoveredStar;
+    private int _selectedStar;
+    private bool _submitted;
+
+    private void Rate(int stars)
+    {
+        _selectedStar = stars;
+        var (avg, count) = RecipeService.SubmitRating(RecipeId, stars);
+        AverageRating = avg;
+        RatingCount = count;
+        _submitted = true;
+    }
+}
