            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
            Steps = ["Brown ground beef with diced onion.", "Add taco seasoning and water; simmer until thickened.", "Warm taco shells in the oven.", "Fill shells with beef mixture.", "Top with shredded lettuce, diced tomato, cheese, and sour cream."],
            AverageRating = 4.1, RatingCount = 27
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cake with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
