            AverageRating = 4.9, RatingCount = 42
        },
        new()
        {
            Id = 7, Title = "Greek Salad", Category = "Salads",
            Description = "A refreshing Mediterranean salad with feta and olives.",
            Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Red wine vinegar", "Oregano"],
            Steps = ["Chop cucumber, tomatoes, and red onion into chunks.", "Combine vegetables in a large bowl.", "Add olives and crumbled feta.", "Drizzle with olive oil and red wine vinegar.", "Season with oregano, salt, and pepper; toss gently."],
            AverageRating = 4.2, RatingCount = 18
        },
        new()
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh, creamy avocado dip with lime and cilantro.",
