            AverageRating = 4.4, RatingCount = 12
        },
        new()
        {
            Id = 10, Title = "Palak Paneer", Category = "Indian",
            Description = "Creamy spinach curry with cubes of paneer cheese.",
            Ingredients = ["Spinach", "Paneer", "Onion", "Garlic", "Ginger", "Green chili", "Cream", "Cumin", "Garam masala"],
            Steps = ["Blanch spinach and blend into a smooth puree.", "Fry paneer cubes until golden; set aside.", "Sauté onion, garlic, ginger, and green chili.", "Add spices, then stir in spinach puree.", "Simmer 10 minutes; add cream and paneer.", "Serve hot with naan or rice."],
            AverageRating = 4.5, RatingCount = 16
        }
    ];

