    [
        new() { Name = "Italian", Description = "Pasta, pizza, and Mediterranean classics", Icon = "🍝", RecipeCount = 2 },
        new() { Name = "Indian", Description = "Rich curries and aromatic spice blends", Icon = "🍛", RecipeCount = 2 },
        new() { Name = "Asian", Description = "Stir-fries, noodles, and umami flavors", Icon = "🥢", RecipeCount = 2 },
        new() { Name = "Mexican", Description = "Bold flavors with fresh salsas and spices", Icon = "🌮", RecipeCount = 2 },
        new() { Name = "Desserts", Description = "Sweet treats and indulgent bakes", Icon = "🍰", RecipeCount = 1 },
        new() { Name = "Salads", Description = "Fresh, healthy, and colorful bowls", Icon = "🥗", RecipeCount = 1 }
    ];

    private readonly Dictionary<int, List<int>> _ratings = [];
    private readonly Lock _ratingsLock = new();

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public (double Average, int Count) SubmitRating(int recipeId, int stars)
    {
        stars = Math.Clamp(stars, 1, 5);
        lock (_ratingsLock)
        {
            if (!_ratings.ContainsKey(recipeId))
                _ratings[recipeId] = [];

            _ratings[recipeId].Add(stars);

            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                var allRatings = _ratings[recipeId];
                recipe.AverageRating = Math.Round(allRatings.Average(), 1);
                recipe.RatingCount += 1;
            }

            return (recipe?.AverageRating ?? 0, recipe?.RatingCount ?? 0);
        }
    }

    public void AddRecipe(string title, string ingredients, string steps)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = title,
            Category = "Community",
            Description = $"A community-submitted recipe for {title}.",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });

        var community = _categories.FirstOrDefault(c => c.Name == "Community");
        if (community is null)
        {
            _categories.Add(new RecipeCategory
            {
                Name = "Community",
                Description = "Recipes shared by our community members",
                Icon = "👨‍🍳",
                RecipeCount = 1
            });
        }
        else
        {
            community.RecipeCount++;
        }
    }
}

